INSERT INTO `nps_feedback` (`id`, `nps`, `remark`, `category`, `sentiment`, `priority`, `emotion`, `observation`, `recommendation`, `keywords`, `confidence_score`, `created_at`, `updated_at`) VALUES
	(1, 10, 'Idfc first bank  ka app very smooth ', 'App / Online Banking related', 'Positive', 'Low', 'Satisfied', 'The user finds the IDFC First Bank app to be very smooth.', 'Continue to maintain and enhance the app\'s performance to ensure user satisfaction. Regular updates and user feedback can help identify areas for improvement. Promote the app\'s features to attract more users.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(2, 10, 'Please open some branches of your bank in rural areas .', 'Branch Access & Location related', 'Neutral', 'Medium', 'Frustration', 'The user is frustrated with the lack of branches in rural areas.', 'Consider expanding branch locations to underserved rural areas to improve accessibility. Conduct market research to identify potential locations. This could enhance customer satisfaction and attract new clients.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(3, 4, 'I had requested to change my number to UK number from Indian. Took almost a week to do. I filled out form and emailed with passport. After I check the updated number it turns out to be a wrong number, in spite of being right on the form I filled out. ', 'KYC / Video KYC Process related', 'Negative', 'High', 'Disappointment', 'The user experienced significant delays and errors in changing their phone number.', 'Implement a more efficient process for updating customer information to avoid delays. Ensure that staff are trained to double-check information for accuracy. Consider automating parts of the process to reduce human error.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(4, 10, 'Everything is very smooth and user friendly interface \nI am glad to using idfc first bank ', 'Satisfied Customer', 'Positive', 'Low', 'Satisfied', 'The user appreciates the smooth and user-friendly interface of the app.', 'Continue to gather user feedback to maintain the app\'s user-friendly design. Regularly update the interface based on user preferences and technological advancements. Promote positive user experiences to attract new customers.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(5, 9, 'Mr. Mohan Annanagar deputy Manager did excellent job with good follow up tii opening SA related activities. ', 'Satisfied Customer', 'Positive', 'Medium', 'Satisfied', 'The user commends the deputy manager for excellent service and follow-up.', 'Recognize and reward employees who provide exceptional service to encourage a culture of excellence. Share positive feedback with the team to motivate others. Consider implementing a customer service training program to enhance overall service quality.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(6, 9, 'Your executive by the name Shraddha who works in the Chembur Branch has been really helpful throughout the process. I loved her attitude and behaviour. There is nothing else required to improve the experience provided by the bank.', 'Agent Behaviour', 'Positive', 'High', 'Anger', 'The user is upset about unprofessional treatment and service rejection without genuine reasons.', 'Review and improve the communication process regarding service rejections to ensure transparency. Train staff to handle customer complaints with empathy and professionalism. Establish a feedback loop to address customer concerns seriously.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(7, 7, 'When the bank provide a reason for rejecting a service, verify that it\'s genuine. It\'s not a platform to joke. Be serious about banking. I will not recommend your bank to anyone because the way I was treated was extremely unprofessional and unacceptable. I didn\'t close the account considering the sincerity of the bank employee who did the process swiftly. I seldom think even this feedback will be taken seriously.', 'Service Dissatisfaction', 'Negative', 'Low', 'Satisfied', 'The user is happy with the application and service provided so far.', 'Maintain the current level of service and continue to engage with customers for feedback. Regularly update users on new features and improvements. Consider loyalty programs to reward satisfied customers.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(8, 10, 'I am happy with the application and service provided till date ', 'Happy with Service', 'Positive', 'Medium', 'Frustration', 'The user suggests training customers to use the app effectively.', 'Develop educational resources such as tutorials and FAQs to help customers navigate the app. Consider hosting webinars or in-branch sessions to provide hands-on training. This could enhance user experience and retention.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(9, 9, 'You must train your customers to use your app. Yhis is very important to retain customers ', 'App / Online Banking related', 'Negative', 'Low', 'Satisfied', 'The user expresses gratitude for the fast service and mobile app.', 'Continue to prioritize fast service and maintain the app\'s performance. Encourage users to share their positive experiences on social media. Consider implementing a referral program to leverage satisfied customers for new business.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(10, 9, 'Aap doesn\'t work in lower android device ', 'App / Online Banking related', 'Negative', 'High', 'Frustration', 'The remark indicates dissatisfaction with the app\'s functionality on lower Android devices.', 'Consider optimizing the app for lower-end Android devices to enhance accessibility. Conduct user testing to identify specific issues faced by users on these devices. Providing clear communication about device compatibility can also help manage user expectations.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(11, 7, 'Add online joint account facility.\nShould be able to open joint account irrespective of the present address, since you can take adhaar consent to self sign current address.', 'Account Opening Experience', 'Negative', 'Medium', 'Disappointment', 'The user is disappointed with the lack of an online joint account facility and the limitations based on address.', 'Implement an online joint account feature that allows users to open accounts regardless of their current address. Ensure that the process includes a method for verifying identity and address through Aadhaar consent. This could improve customer satisfaction and attract more users.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(12, 7, 'I  want to experience the services before commenting.  I am also a shareholder holding few lac shares. I want to observe the Bank gor sometime.', 'Happy with Service', 'Positive', 'Medium', 'Neutral', 'The user wants to experience the services before providing feedback, indicating a cautious approach.', 'Encourage users to explore your services by offering a trial period or demo. Provide clear information about the benefits of your services to build trust. Engaging with shareholders can also enhance their experience and loyalty.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(13, 10, 'Everything was perfect the sales executive was very kind and help me in every process which saves a lot of time required to open an account.Overall it was a good experience.', 'Seamless Account opening', 'Positive', 'High', 'Satisfied', 'The user had a positive experience with the sales executive, highlighting efficiency and kindness.', 'Continue to train sales executives on customer service and efficiency. Recognize and reward employees who provide exceptional service to maintain high standards. Collect feedback from customers to identify areas for further improvement.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(14, 0, 'The executive told me to open a zero balance account. After opening, I got a message that your average balance is Rs 25,000 so I want to close this account without using your saving account services.', 'Account Closure Request', 'Negative', 'High', 'Frustration', 'The user is frustrated by receiving conflicting information about the account balance requirements.', 'Clarify communication regarding account types and their requirements to avoid confusion. Ensure that all customer-facing staff are well-informed about account policies. Consider revising the messaging sent to customers to align with the actual account features.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(15, 9, 'Nothing specific\nJust practice to keep some human ? intraction on regular basis.', 'Satisfied Customer', 'Positive', 'Low', 'Neutral', 'The user suggests maintaining human interaction, indicating a desire for personal touch.', 'Incorporate regular human interaction in customer service processes, such as follow-up calls or in-person consultations. This can enhance customer relationships and satisfaction. Consider feedback mechanisms to gauge the effectiveness of these interactions.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(16, 8, 'Minimum balance is too high ,it is 25k lesser than that could be great , other features are great \n', 'Charges, Fees, Balance Requirements', 'Neutral', 'Medium', 'Frustration', 'The user finds the minimum balance requirement too high and suggests lowering it.', 'Evaluate the minimum balance requirements and consider adjusting them to be more competitive. Conduct market research to understand customer expectations and preferences. Communicate any changes clearly to existing and potential customers.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(17, 10, 'No... everything this is perfect.', 'Satisfied Customer', 'Positive', 'Low', 'Satisfied', 'The user expresses overall satisfaction with the services provided.', 'Maintain the current level of service quality and continue to seek feedback for ongoing improvement. Celebrate positive feedback internally to motivate staff. Consider implementing a loyalty program to reward satisfied customers.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(18, 9, 'Online application verification of documents do get notary sign can be eliminated will make faster submission of application for approval. ', 'App / Online Banking related', 'Positive', 'Medium', 'Frustration', 'The user suggests eliminating the notary sign requirement for online document verification to speed up the process.', 'Review the document verification process to identify areas for improvement. Explore alternatives to notary requirements that can streamline the application process. Communicate any changes to customers to enhance their experience.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(19, 10, 'Everything is good keep it up ???', 'Satisfied Customer', 'Positive', 'Low', 'Satisfied', 'The user is pleased with the overall service and encourages the team to keep it up.', 'Continue to deliver high-quality service and maintain open lines of communication with customers. Regularly solicit feedback to ensure that customer satisfaction remains high. Recognize and celebrate team achievements to foster a positive work environment.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(20, 9, 'I am impressed with your Service and the process of opening an account with  was faster. \nGiving a handout with all the types of account and the benefits of each account would have been still better. I know the agents explained it but still a leaflet would be better. thank you ', 'Seamless Account opening', 'Positive', 'Medium', 'Satisfied', 'The customer is impressed with the service and the speed of the account opening process. They suggest providing a leaflet for better clarity on account types.', 'Consider creating a comprehensive leaflet that outlines the different types of accounts and their benefits. This could enhance customer understanding and satisfaction. Additionally, ensure that agents are trained to provide this information effectively during the account opening process.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(21, 1, 'Your promote yourself as online banking but that doesnt work.\nBranch doesnt allow us to open 10k MAB account \nAlmost convinces us for 25k MaB account\n\nI wanted a joint account but they made it single and the 2nd partner is not yet added \n1 week has passed \n\nI would have choosen other bank over this pathetic services \n', 'Service Dissatisfaction', 'Negative', 'High', 'Frustration', 'The customer is frustrated with the limitations of online banking and the issues faced while trying to open a joint account.', 'Address the concerns regarding online banking functionality and ensure that branch staff are well-informed about account options. Implement a streamlined process for opening joint accounts to avoid delays and improve customer experience. Regular training sessions for staff could help mitigate such issues.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(22, 0, 'Miss-selled by employee. I am want to close this account', 'Account Closure Request', 'Negative', 'High', 'Disappointment', 'The customer feels they were mis-sold a product and now wish to close their account.', 'Investigate the circumstances surrounding the mis-selling incident and provide a resolution to the customer. Implement a review process for sales practices to ensure that customers are fully informed about products. Consider offering a follow-up to understand their concerns better and potentially retain their business.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(23, 9, 'I m satisfied with bank employee \nAnd overall good Bank ', 'Satisfied Customer', 'Positive', 'Medium', 'Satisfied', 'The customer expresses satisfaction with the bank employee and overall service.', 'Recognize and reward the employee for their excellent service to encourage continued high performance. Gather feedback from satisfied customers to identify what aspects of service are most appreciated and ensure these are maintained across the organization.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(24, 7, 'Your credit card verification team seems to be incompetent. They were too lazy to verify my office address and as a result my application got rejected. Thank you. ', 'Credit Card related', 'Negative', 'High', 'Frustration', 'The customer is frustrated with the incompetence of the credit card verification team, leading to a rejected application.', 'Review the verification process for credit card applications to identify inefficiencies. Provide additional training for the verification team to ensure thorough and timely processing of applications. Consider implementing a feedback mechanism for customers to report issues with the application process.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(25, 10, 'Shubham is very good person, he\'s way of talking and approch was awesome.', 'Competence Staff', 'Positive', 'Medium', 'Satisfied', 'The customer appreciates the service provided by an employee named Shubham.', 'Highlight Shubham\'s positive interaction as a model for customer service excellence. Encourage other employees to adopt similar communication styles and approaches. Consider sharing customer testimonials to motivate staff and improve overall service quality.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(26, 6, 'Please done your work on time', 'Service Delays / Account Issues', 'Negative', 'Medium', 'Frustration', 'The customer requests timely completion of tasks, indicating a lack of efficiency.', 'Implement a system to track and manage customer requests to ensure timely completion. Regularly review performance metrics related to task completion and address any bottlenecks. Communicate with customers about expected timelines to manage their expectations.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(27, 9, 'Your AMB on savings account is too hight that is 25000.which didn\'t satisfy students like me and other poor people like wage earners.', 'Charges, Fees, Balance Requirements', 'Negative', 'Medium', 'Disappointment', 'The customer is dissatisfied with the high minimum balance requirement for the savings account.', 'Reassess the minimum balance requirements for savings accounts, especially for students and low-income earners. Consider introducing more flexible options or lower minimum balances to accommodate a wider range of customers. Engage with customers to understand their needs and adjust offerings accordingly.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(28, 10, 'Heramb is the best RM', 'Agent Behaviour', 'Positive', 'Medium', 'Satisfied', 'The customer praises an employee named Heramb as the best relationship manager.', 'Recognize Heramb\'s contributions to customer satisfaction and consider sharing their best practices with the team. Encourage a culture of excellence in customer service by providing training sessions based on successful employee interactions. Use positive feedback to motivate other staff members.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(29, 10, 'Fast and reliable banking with latest technology ', 'Satisfied Customer', 'Positive', 'Low', 'Satisfied', 'The customer appreciates the fast and reliable banking services with modern technology.', 'Continue to invest in technology that enhances the banking experience for customers. Regularly solicit feedback on technological features to ensure they meet customer needs. Promote these advancements to attract new customers and retain existing ones.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(30, 10, 'For now, so far so good.', 'Satisfied Customer', 'Positive', 'Medium', 'Neutral', 'The remark indicates a satisfactory experience with the service provided.', 'Continue to maintain the current level of service to ensure customer satisfaction. Regularly check in with customers to gather feedback on their experiences. Consider implementing a follow-up process to ensure that customers feel valued and heard.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(31, 10, 'Thanku Aruna Ma\'am And Piyush for your Prompt service and immediate action.\nIt was so easy where I was completely happy for ur service rendered with Proper Knowledge of yours ', 'Happy with Service', 'Positive', 'High', 'Satisfied', 'The customer expressed gratitude for the prompt service and knowledge of the staff.', 'Recognize and reward the employees mentioned for their excellent service. Encourage the team to maintain this level of responsiveness and knowledge. Share this positive feedback within the organization to motivate other staff members.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(32, 10, 'The arrival of debit card & welcome kit arrival is taking time. It has been 1 week since I had opened a savings account but didn\'t yet received welcome kit or debit card. I was told that it would take 3-4 working days to arrive.', 'Debit Card / Cheque Book / Welcome Kit related', 'Negative', 'High', 'Frustration', 'The customer is frustrated due to the delay in receiving their welcome kit and debit card.', 'Investigate the cause of the delay in the welcome kit and debit card delivery. Communicate proactively with customers about expected timelines and any delays. Consider improving the logistics process to ensure timely delivery in the future.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(33, 0, 'Deposit amount so very expensive ', 'Charges, Fees, Balance Requirements', 'Negative', 'Medium', 'Disappointment', 'The customer finds the deposit amount to be very expensive.', 'Review the deposit amounts and consider if they align with market standards. If possible, offer promotional rates or lower deposit options to attract more customers. Communicate the value and benefits of the current deposit amounts to justify the costs.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(34, 10, 'à¤‡à¤¸à¤®à¥‡à¤‚ à¤•à¥‹à¤ˆ à¤­à¥€ à¤šà¤¾à¤°à¥à¤œ à¤¨à¤¹à¥€à¤‚ à¤²à¤—à¤¤à¤¾ à¤‡à¤¸ à¤²à¤¿à¤ ', 'Charges, Fees, Balance Requirements', 'Positive', 'Low', 'Neutral', 'The customer appreciates that there are no charges involved.', 'Highlight the no-charge feature in marketing materials to attract more customers. Ensure that this information is easily accessible on the website and in customer communications. Continue to monitor customer satisfaction regarding fees and charges.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(35, 10, 'To carry the ATM card safely, provide an ATM card envelope in the welcome kit.', 'ATM related issues', 'Positive', 'Medium', 'Neutral', 'The customer suggests providing an ATM card envelope in the welcome kit for safety.', 'Consider adding an ATM card envelope to the welcome kit as a value-added feature. This could enhance the customer experience and show that the bank cares about their security. Gather feedback on this suggestion to assess its potential impact.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(36, 10, 'The experience of opening a Savings Account with IDFC FIRST Bank was excellent. The process was smooth, quick, and user-friendly. The staff was supportive and guided me well through each step. I really appreciate the digital options and the transparency throughout. Honestly, I canâ€™t think of anything that needs improvementâ€”it was a seamless experience\n', 'Seamless Account opening', 'Positive', 'High', 'Satisfied', 'The customer had an excellent experience opening a savings account, praising the smooth process and supportive staff.', 'Use this positive feedback to reinforce best practices among staff. Consider creating case studies or testimonials to showcase successful customer experiences. Continue to invest in training and resources that support a seamless account opening process.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(37, 9, 'For signature upload and check book request process is not user friendly ', 'Debit Card / Cheque Book / Welcome Kit related', 'Negative', 'High', 'Frustration', 'The customer finds the signature upload and checkbook request process to be not user-friendly.', 'Conduct a usability study on the signature upload and checkbook request processes. Gather feedback from users to identify specific pain points and areas for improvement. Implement changes based on user feedback to enhance the overall user experience.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(38, 9, 'there was 2 adresss link with account. that is permant adresss and current adresss, but mobile banking only show communiaction adresss(permmant address). if your want change currentt adresss there is no option. u can fix this', 'App / Online Banking related', 'Negative', 'Medium', 'Frustration', 'The customer is frustrated with the mobile banking app\'s address display and update options.', 'Review the mobile banking app\'s functionality regarding address management. Consider adding features that allow users to easily view and update their current address. Communicate any updates or changes to customers to improve their experience.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(39, 7, 'The interest rates are good which was the only reason for opening the account', 'Seamless Account opening', 'Positive', 'Low', 'Satisfied', 'The customer is satisfied with the interest rates offered.', 'Promote the competitive interest rates in marketing campaigns to attract new customers. Ensure that current customers are aware of the benefits of their accounts. Monitor interest rates regularly to remain competitive in the market.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(40, 7, 'Along with the process of opening an account being easy and secure, the facilities that should be provided should be provided on time. And despite having an old relationship with me, I have not received any good credit card offer till now. ', 'Credit Card related', 'Neutral', 'Medium', 'Disappointment', 'The customer feels let down due to the lack of timely credit card offers despite a long-standing relationship with the bank.', 'The bank should review its credit card offer process to ensure that long-term customers receive timely and relevant offers. Implementing a system to track customer relationships and preferences could enhance customer satisfaction. Additionally, proactive communication about available offers could help in retaining customer loyalty.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(41, 9, 'when I visit city centre branch of gwalior. I wanted a future first student saving account but the employee working there tells that that don\'t offer such saving account but they offer pratham account so I unfortunately have to open the pratham account but I wish I could get future first student saving account. Just this is the thing which I don\'t like ', 'Branch Access & Location related', 'Negative', 'Medium', 'Frustration', 'The customer was disappointed when informed that the desired student saving account was not available, leading to an unexpected account opening.', 'The bank should ensure that employees are well-informed about all available account options to provide accurate information to customers. Training sessions could be beneficial to enhance staff knowledge. Additionally, offering personalized consultations could help customers find the best account that meets their needs.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(42, 0, 'I have funding in my account since 5 days but still I am not able to withdraw it', 'Customer Support & Follow-up', 'Negative', 'High', 'Frustration', 'The customer is unable to withdraw funds that have been in their account for five days, indicating a significant issue.', 'Immediate investigation into the withdrawal issue is necessary to resolve the customer\'s problem. The bank should enhance its communication regarding fund availability and withdrawal processes. Implementing a system to notify customers of any delays or issues could improve their experience.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(43, 10, 'E bank account Nammge help full agutte ', 'Generic', 'Neutral', 'Low', 'Satisfied', 'The customer finds the e-bank account helpful, indicating a positive experience.', 'The bank should continue to promote the benefits of the e-bank account to attract more customers. Gathering feedback from satisfied customers can help in refining the service further. Additionally, highlighting success stories could enhance the bank\'s reputation.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(44, 10, 'The people from the bank are very supportive. The Agent came multiple times to my office to get my work done. I like this aspect, he even bought one manager to make myself understand about the benefits and perks. Having said that I was little disappointed with Forex Card Process, the agent said I can get that card immediately after opening the account, when I went to the bank, they said you have to come before you leave to the other country. I think there is a miscommunication, but I am okay with it.', 'Seamless Account opening', 'Positive', 'Medium', 'Disappointment', 'The customer experienced miscommunication regarding the Forex Card process, leading to disappointment.', 'The bank should improve communication between agents and customers to ensure clarity regarding product offerings. Regular training for staff on product details and customer expectations can help prevent such issues. A follow-up system after account opening could also clarify any misunderstandings.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(45, 2, 'Very poor knowledge and expertise on account opening procedure ', 'Account Opening Experience', 'Negative', 'High', 'Frustration', 'The customer expressed dissatisfaction with the poor knowledge and expertise of staff regarding account opening procedures.', 'The bank must invest in comprehensive training programs for employees to enhance their knowledge of account opening procedures. Regular assessments and updates on policies can ensure staff remain informed. Customer feedback should be actively sought to identify areas needing improvement.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(46, 10, 'Excellent approach and follow up by your Bank\'s representative', 'Satisfied Customer', 'Positive', 'High', 'Satisfied', 'The customer praised the excellent approach and follow-up by the bank\'s representative.', 'The bank should recognize and reward employees who provide exceptional service to encourage continued excellence. Sharing positive feedback with the team can motivate staff. Additionally, implementing a customer satisfaction survey could help maintain high service standards.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(47, 8, 'Good feedback from my son ', 'Satisfied Customer', 'Positive', 'Low', 'Satisfied', 'The customer received good feedback from their son, indicating a positive experience.', 'The bank should leverage positive customer experiences to attract new clients. Encouraging satisfied customers to share their experiences through testimonials or referrals can enhance the bank\'s reputation. Engaging with families could also create a more inclusive banking environment.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(48, 5, 'A on my account they told I will get first tap stickers as well as they didnâ€™t tell that I will not get separate card for my guardian and itâ€™s very restrictive account, so itâ€™s no use for us . Felt waste of time .', 'Customer Support & Follow-up', 'Negative', 'Medium', 'Disappointment', 'The customer felt restricted by the account features and was disappointed with the lack of communication regarding account limitations.', 'The bank should provide clear and comprehensive information about account features and limitations at the time of account opening. Offering flexible account options that cater to different customer needs could enhance satisfaction. Regularly reviewing account offerings based on customer feedback can also help in improving services.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(49, 10, 'Kiny prlvide minimum amb maintance to 2500  rs ', 'Charges, Fees, Balance Requirements', 'Neutral', 'Low', 'Neutral', 'The customer mentioned a minimum maintenance requirement, indicating a need for clarity on account terms.', 'The bank should ensure that all account terms, including maintenance requirements, are clearly communicated to customers. Providing easy access to this information online can help customers make informed decisions. Regular updates on account policies can also enhance transparency.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(50, 0, 'Najafgarh m Bank branch hona ', 'Branch Access & Location related', 'Negative', 'Medium', 'Neutral', 'The remark suggests a desire for a bank branch in Najafgarh, indicating a need for better accessibility.', 'Consider conducting a feasibility study to assess the demand for a new branch in Najafgarh. Engaging with the local community through surveys could provide valuable insights. If the demand is confirmed, plan for a branch that meets the needs of the residents.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(51, 10, 'Allover good service of idfc bank ', 'Happy with Service', 'Positive', 'Low', 'Satisfied', 'The customer expresses overall satisfaction with the service provided by IDFC Bank.', 'Continue to maintain high service standards and consider gathering more detailed feedback to identify specific areas of strength. Highlighting these positive aspects in marketing materials could attract new customers.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(52, 9, 'If I find anything, I will surely give my feedback.', 'Satisfied Customer', 'Positive', 'Low', 'Neutral', 'The customer is open to providing feedback in the future, indicating a willingness to engage.', 'Encourage this customer to share their feedback by creating a simple and accessible feedback mechanism. Regular follow-ups can help in building a stronger relationship and understanding customer needs better.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(53, 10, 'Already improved than others.. so keep it up \n', 'Satisfied Customer', 'Positive', 'Medium', 'Satisfied', 'The customer acknowledges improvements in service compared to competitors, suggesting a positive trend.', 'Continue to monitor service quality and implement further improvements based on customer feedback. Communicate these enhancements to customers to reinforce their positive perception and loyalty.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(54, 9, 'Aadhar linked mobile attached with account , provide option to add another mobile number for bank account', 'KYC / Video KYC Process related', 'Negative', 'High', 'Frustration', 'The customer is frustrated with the lack of options to add another mobile number linked to their Aadhar account.', 'Implement a feature that allows customers to easily add or update their mobile numbers linked to their accounts. Clear communication about this feature should be provided to customers to enhance their experience.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(55, 7, 'Again behaviour of the branch managers, and the customer ask for some clarification about the Bank name board at Dharmapuri branch', 'Agent Behaviour', 'Negative', 'High', 'Frustration', 'The customer is frustrated with the behavior of branch managers and unclear communication regarding account requirements.', 'Conduct training sessions for branch staff to improve customer service and communication skills. Establish clear guidelines for account requirements and ensure all staff are informed to prevent misinformation.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(56, 1, 'Agent ka call nhi aaya ', 'Customer Support & Follow-up', 'Negative', 'High', 'Frustration', 'The customer is frustrated due to a lack of communication from the agent and pressure to deposit a large sum.', 'Review the communication protocols for agents to ensure timely follow-ups with customers. Additionally, clarify account upgrade requirements to prevent misunderstandings and ensure that customers feel valued and respected.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(57, 2, 'My talk for the 6 family accounts as first wealth account and AMB for all account altogether 10 lakh. One account opend as first wealth and 2 as normal account, one account in process and process of remaining 2 yet to start. Now branch official calling us and make presuure to deposit 50 lakh first to move normal account in first wealth and use harsh word. I talk to relationship manager and get to know that he is ill. After 3 days I again call him and after knowing that he recover, tell the issue. I surprise that relationship manager balim me that i am lying. \nAfter this I ask him to provide contact number of brach head but the same was not provided. I left no other option but to raise the complain with customer care. After lodging the compalin I get call from branch head and he again ask for 50 Lakh overall relationship to upgrade the other family members account whereas at the time of account opening i was informed AMB 10 lakh or AUM 25 lakh or ORV 50 lakh but all official including branch head mow read this OR as AND.\nI ask the branch head if so then I am not interested in maintaining the accounts and share him email send by branch official before opeing the accounts, in which he clearly mentioned that all account cumulative AMB will be 10 lakh only. Thereafter he ready to upgrade the accounts and promise to send a email in this regard but the same was still not received.', 'Mis-selling', 'Negative', 'Medium', 'Satisfied', 'The customer appreciates Mr. Thohid\'s knowledge and communication skills, indicating a positive experience.', 'Recognize and reward Mr. Thohid for his excellent service to encourage continued high performance. Consider sharing his approach with other staff members as a model for customer interaction.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(58, 10, 'Mr.Thohid has good Knowledge about accounts in banking sector...\nFelt so happy and good Communication good experience overall Satisfied ', 'Seamless Account opening', 'Positive', 'Low', 'Satisfied', 'The customer expresses satisfaction with the overall services provided.', 'Maintain the current level of service quality and consider implementing a regular feedback loop to ensure ongoing customer satisfaction. Highlighting positive customer experiences can also enhance the bank\'s reputation.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(59, 10, 'The person who assisted me in opening the account Thiru Vetriselvan was really very good person. His service in opening the account was really very good.', 'Happy with Service', 'Positive', 'High', 'Satisfied', 'The customer had a positive experience with Thiru Vetriselvan during the account opening process, highlighting his good service.', 'Continue to recognize and reward employees like Thiru Vetriselvan for their excellent customer service. Consider implementing a feedback system where customers can easily share their positive experiences with specific staff members.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(60, 7, 'Actually, Everything is working great here. The only thing which I was looking for was the particular debit card variant which was missing. But, never mindâ€¦ will adjust this time. Actually receiving exactly what you are expecting creates greater satisfaction which was missing in this case but other than this everything else just worked pretty well and  great!!!!!!\nThank u so much !!!', 'Debit Card / Cheque Book / Welcome Kit related', 'Positive', 'Medium', 'Disappointment', 'The customer expressed disappointment over the unavailability of a specific debit card variant, despite overall satisfaction with the service.', 'Investigate the reasons behind the unavailability of certain debit card variants and work on improving the product offerings. Communicate with customers about the availability of products to manage expectations better.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(61, 10, 'Paper less service..\nAwesome \nFaster \nSmooth \nShaper \nSmarter\nBetter then other Bank\n\nBt I don\'t Like The Yours Courier Partner Service. ', 'Happy with Service', 'Positive', 'Medium', 'Frustration', 'The customer praised the paperless service but expressed dissatisfaction with the courier partner\'s service.', 'Evaluate the performance of the current courier partner and consider alternatives if service levels do not meet customer expectations. Ensure that customers are informed about the delivery process and any potential delays.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(62, 10, 'Best bank for account opening ', 'Competence Staff', 'Positive', 'High', 'Satisfied', 'The customer considers the bank to be the best for account opening, indicating high satisfaction.', 'Leverage this positive feedback in marketing materials to attract new customers. Encourage satisfied customers to share their experiences on social media or review platforms.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(63, 10, 'Very good service ang good vehiviour', 'Happy with Service', 'Positive', 'High', 'Satisfied', 'The customer appreciated the good service and behavior of the staff.', 'Continue to train staff on customer service excellence and maintain a positive atmosphere in branches. Regularly gather feedback to ensure that service quality remains high.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
