	(70, 10, 'Very goOD service and system\n', 'Happy with Service', 'Positive', 'High', 'Satisfied', 'The customer is pleased with the service and system provided.', 'Leverage this positive feedback in marketing materials to attract new customers. Highlight the strengths of your service and system in promotional campaigns.', NULL, 0.90, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
