	(201, 10, 'Great customer service and regular follow up ', 'Happy with Service', 'Positive', 'Medium', 'Satisfied', 'The customer appreciates great customer service and regular follow-ups.', 'Maintain the current level of customer service and follow-up practices. Consider formalizing a customer feedback loop to continuously improve service quality based on customer insights.', NULL, 0.60, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
	(202, 0, 'Call me I ll let you ', 'Customer Support & Follow-up', 'Negative', 'Low', 'Neutral', 'The remark suggests a willingness to communicate further, indicating a neutral sentiment.', 'Encourage the customer to reach out by providing clear contact information and ensuring prompt responses to inquiries. This can enhance customer engagement and satisfaction.', NULL, 0.30, '2026-02-17 18:56:39', '2026-02-17 18:56:39'),
